import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import styles from './NotificationBell.module.css';

const NotificationBell = () => {
    const navigate = useNavigate();
    const [isOpen, setIsOpen] = useState(false);
    const [notifications, setNotifications] = useState([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loading, setLoading] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);
    
    const dropdownRef = useRef(null);

    // Закрытие при клике вне компонента
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // POLLING: Проверка новых уведомлений (каждые 10 сек)
    useEffect(() => {
        fetchNotifications(1, true); // Первая загрузка
        const interval = setInterval(() => fetchNotifications(1, true, true), 10000);
        return () => clearInterval(interval);
    }, []);

    const fetchNotifications = async (pageNum = 1, reset = false, silent = false) => {
        if (loading && !silent) return;
        if (!silent) setLoading(true);
        
        try {
            const token = localStorage.getItem('access');
            if (!token) return;

            const resp = await axios.get(`http://10.124.215.133:8000/api/notifications/?page=${pageNum}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            
            const newNotifs = resp.data.results || [];
            
            if (reset) {
                setNotifications(newNotifs);
                // Считаем непрочитанные (если бэк не отдает count отдельно)
                const unread = newNotifs.filter(n => !n.is_read).length; 
                // В идеале бэк должен отдавать поле unread_count в метаданных
                setUnreadCount(unread > 9 ? '9+' : unread);
            } else {
                setNotifications(prev => [...prev, ...newNotifs]);
            }
            
            setHasMore(!!resp.data.next);
            setPage(pageNum);

        } catch (err) {
            console.error("Ошибка уведомлений", err);
        } finally {
            if (!silent) setLoading(false);
        }
    };

    const handleLoadMore = (e) => {
        e.stopPropagation();
        fetchNotifications(page + 1);
    };

    const handleMarkRead = async (e) => {
        e.stopPropagation();
        try {
            const token = localStorage.getItem('access');
            await axios.post('http://10.124.215.133:8000/api/notifications/mark_all_read/', {}, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            // Обновляем локально
            setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
            setUnreadCount(0);
        } catch (err) {
            console.error(err);
        }
    };

    const handleNotificationClick = (notif) => {
        // Логика перехода (например, на профиль отправителя)
        if (notif.sender) {
             // Если у sender есть handle, используем его, иначе id
             const target = notif.sender.handle || notif.sender.id;
             navigate(`/${target}`);
             setIsOpen(false);
        }
    };

    return (
        <div className={styles.container} ref={dropdownRef}>
            {/* Колокольчик */}
            <div className={styles.bellWrapper} onClick={() => setIsOpen(!isOpen)}>
                <img src="/images/bell.svg" alt="Notifications" className={styles.bellIcon} />
                {unreadCount !== 0 && (
                    <div className={styles.badge}>{unreadCount}</div>
                )}
            </div>


            {/* Выпадающее окно */}
            {isOpen && (
                <div className={styles.dropdown}>
                    <div className={styles.header}>
                        <span className={styles.title}>Уведомления</span>
                        <button className={styles.markReadBtn} onClick={handleMarkRead}>
                            Прочитать все
                        </button>
                    </div>
                    
                    <div className={styles.list}>
                        {notifications.length > 0 ? (
                            notifications.map((notif) => (
                                <div 
                                    key={notif.id} 
                                    className={`${styles.item} ${!notif.is_read ? styles.unread : ''}`}
                                    onClick={() => handleNotificationClick(notif)}
                                >
                                    <img 
                                        src={notif.sender?.avatar || "/images/profile.svg"} 
                                        alt="ava" 
                                        className={styles.avatar}
                                        onError={(e)=>{e.target.src="/images/profile.svg"}}
                                    />
                                    <div className={styles.content}>
                                        <div className={styles.text}>
                                            <span className={styles.name}>{notif.sender?.nickname || "Пользователь"}</span>
                                            {" "}{notif.text}
                                        </div>
                                        <div className={styles.date}>
                                            {new Date(notif.created_at).toLocaleDateString()}
                                        </div>
                                    </div>
                                    {!notif.is_read && <div className={styles.dot}></div>}
                                </div>
                            ))
                        ) : (
                            <div className={styles.empty}>Нет новых уведомлений 💤</div>
                        )}
                        
                        {loading && <div className={styles.loader}>Загрузка...</div>}
                        
                        {!loading && hasMore && (
                            <button className={styles.loadMoreBtn} onClick={handleLoadMore}>
                                Показать еще
                            </button>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default NotificationBell;
